import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"T2V-CompBench: A Comprehensive Benchmark for Compositional Text-to-video Generation","description":"","frontmatter":{"title":"T2V-CompBench: A Comprehensive Benchmark for Compositional Text-to-video Generation","arxiv":"2407.14505","date":"2024-07-19","authors":"Kaiyue Sun, Kaiyi Huang, Xian Liu, Yue Wu, Zihan Xu, Zhenguo Li, Xihui Liu","categories":"cs.CV","topics":"视频生成评测, 组合性生成, MLLM 评测器","outline":[2,2]},"headers":[],"relativePath":"papers/2407.14505.md","filePath":"papers/2407.14505.md","lastUpdated":null}'),e={name:"papers/2407.14505.md"};function l(i,s,r,c,m,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="t2v-compbench-a-comprehensive-benchmark-for-compositional-text-to-video-generation" tabindex="-1">T2V-CompBench: A Comprehensive Benchmark for Compositional Text-to-video Generation <a class="header-anchor" href="#t2v-compbench-a-comprehensive-benchmark-for-compositional-text-to-video-generation" aria-label="Permalink to &quot;T2V-CompBench: A Comprehensive Benchmark for Compositional Text-to-video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2407.14505" target="_blank" rel="noreferrer">2407.14505</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-07-19</td></tr><tr><td><strong>作者</strong></td><td>Kaiyue Sun, Kaiyi Huang, Xian Liu, Yue Wu, Zihan Xu, Zhenguo Li, Xihui Liu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把&quot;组合性&quot;拆成 7 类共 1400 条含动词的 prompt，并为每一类单独配一个（MLLM / 检测 / 点跟踪）评测器，用人类打分相关性挑出每类的最佳 metric。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/post-training-rl">后训练与强化学习</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 <strong>v2</strong> 全文（v1 提交于 2024-07-19，v2 修订于 2025-01-15，扩充到 23 个被测模型）。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>文生视频模型早已能把&quot;一只狗在草地上跑&quot;生成得很像样，但只要 prompt 里同时出现两个物体、两个属性、两个动作，或者要求属性随时间变化，结果就开始崩：颜色贴到错的物体上、说&quot;向左&quot;却往右飘、说&quot;五只狗&quot;却给三只。这类失败在图像域被系统研究过（T2I-CompBench 等），在视频域却几乎是空白。</p><p>作者把这件事定义为 <strong>compositional text-to-video generation</strong>，并指出它比图像版难一个量级：图像只需要判断单帧里的绑定关系，视频还要判断跨帧的动态——属性是否随时间变化、物体相对背景的真实移动方向、交互过程是否完整发生。既有的 T2V benchmark（VBench、EvalCrafter、FETV、ChronoMagic-Bench）主要评画质、运动质量和单物体的文本对齐，prompt 层面就没有覆盖多物体组合，评测指标层面也没有能刻画跨帧绑定的工具。没有这套东西，&quot;组合性&quot;这个能力维度就无法被优化——这正是本文的价值：它给后训练/对齐类工作提供了一个可被当作目标函数的靶子。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>T2I-CompBench</strong> 已经把图像组合性拆成属性绑定、关系、复杂组合，并配了 BLIP-VQA、检测式 metric，被 PixArt-α、SD3 等基础模型采纳为评测维度。它的问题是评测原语全是单帧的，直接平均到视频上会丢掉全部时序信息。</p><p><strong>VBench / EvalCrafter / FETV</strong> 提供了多维度的视频评测套件。作者的批评很具体：VBench 的 &quot;multiple objects&quot; 维度确实含多物体，但 prompt 形如 &quot;a bird and a cat&quot;，<strong>不含任何动态</strong>；ChronoMagic-Bench 专攻自然的延时变形视频，并刻意排除了&quot;非自然属性变化&quot;，而后者恰恰是考察模型创造性绑定能力的部分。</p><p><strong>常规指标层面</strong>：IS、FID、FVD 度量分布距离，CLIPScore 度量整体语义相似度，它们对&quot;蓝苹果 vs 红苹果&quot;这种细粒度绑定错误几乎不敏感。VPEval 与 VideoDirectorGPT 引入了基于 GroundingDINO 的检测式指标，但前者只做单帧空间关系，后者判断运动方向的方式是<strong>比较首末帧的物体框位置</strong>——一旦相机在动，物体的绝对位移就完全不等于它相对世界的运动方向。这个缺口是本文 tracking-based metric 的直接动机。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在 2024 年中的位置往回看，可用的线索是这样几条：图像域已经证明&quot;组合性&quot;是一个能被 prompt suite + 专用 metric 稳定测出来的独立能力轴；视频域的模型能力刚跨过&quot;能生成连贯短片&quot;的门槛，正好到了可以被细粒度考问的时点；而现有 T2V benchmark 的 prompt 几乎全是单主体，说明大家默认还在解决更基础的问题。</p><p>一个认真的研究者会先问：视频比图像多出来的到底是什么？答案是两条正交的东西——<strong>同一时刻多物体的空间组合</strong>（图像已有），和<strong>跨时刻的状态/位置变化</strong>（图像没有）。于是分类法自然分成空间轴（一致属性绑定、空间关系、数量）与时间轴（动态属性绑定、运动绑定、动作绑定、物体交互）。</p><p>第二个问题是：怎么测？直觉是&quot;用一个大 MLLM 打分就行&quot;。但一旦真的去试，会发现 MLLM 在计数和左右关系上是出了名地不可靠，而在描述&quot;某物体是否在变色&quot;这种细粒度时序变化上又常常直接失灵。所以合理的下一步不是硬上一个统一评测器，而是<strong>承认不同类别需要不同工具</strong>：语义类交给 MLLM，可数/可框类交给检测器，方向类交给点跟踪。最后再用人类打分把&quot;哪类该用哪个工具&quot;这件事验证一遍。本文的结构就是这条路径的直接产物。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频的组合性错误不是一种错误，而是至少三种性质完全不同的错误：语义绑定错（需要理解）、计数与布局错（需要定位）、运动方向错（需要在相机运动下做前景-背景的相对测量）。用一个通用打分器同时测这三种，必然在其中两种上退化成噪声。所以正确做法是<strong>为每一类误差配一个恰好能看见它的传感器</strong>，再用人类标注做一次&quot;传感器选型&quot;。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以运动绑定类的一条 prompt 为例——&quot;A ship sails to the left while a bird flies rightwards&quot;：</p><ol><li><strong>词表构建</strong>：从 VidProM 收集的 167 万条真实用户 T2V prompt 里，用 WordNet 统计名词/动词元类分布，只保留高频且可框定的 &quot;thing&quot; 类名词（如 car、dog），排除 sky 这类无明确边界的 &quot;stuff&quot;；动词只取 move / travel / act 等活跃元类，剔除 think、see、rest。最终得到 260 个名词、200 个动词、80 个属性。</li><li><strong>prompt 生成</strong>：用 GPT-4 按每类的具体要求，从上述词表生成 200 条 prompt，同时返回便于评测的结构化元信息（物体、属性、动作、方向）。全部由人工复核过滤。七类共 1400 条，平均每条 3.6 个名词、1.4 个动词、10.4 个词。</li><li><strong>采样规范</strong>：MLLM 评测取 6 帧，检测式取 16 帧，跟踪式重采样到 8 FPS。</li><li><strong>本例的评测</strong>：用 GroundingSAM 分别拿到前景物体掩码与背景掩码，用 DOT 在两者上做稠密点跟踪，各自求平均运动向量，<strong>取差值</strong>作为物体相对世界的真实运动方向，再与 prompt 里的方向比对。</li><li>若这条 prompt 属于空间关系类，则改走 GroundingDINO 检测 + 规则判定；属于 3D 前后关系则再叠 SAM 掩码与 Depth Anything 深度；属于动态属性绑定则走逐帧 LLaVA 打分（D-LLaVA）；属于一致属性绑定/动作绑定/物体交互则走 Image Grid + LLaVA（6 帧拼成网格，先描述再分项打分，即 Grid-LLaVA）。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化集中在检测式规则。设两个物体框的中心为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，判定&quot;第一个物体在第二个左边&quot;要求水平位移大于垂直位移且方向正确，即</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6891em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:1em;"></span><span class="mord text"><span class="mord cjk_fallback">且</span></span><span class="mspace" style="margin-right:1em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∣.</span></span></span></span></span></p><p>第二个条件是关键：它排除了&quot;其实是上下关系、只是稍微偏了一点左&quot;的伪阳性。单帧得分定义为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3em;vertical-align:-1.25em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size4">{</span></span><span class="mord"><span class="mtable"><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.69em;"><span style="top:-3.69em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span><span class="mpunct">,</span></span></span><span style="top:-2.25em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord">0</span><span class="mpunct">,</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.19em;"><span></span></span></span></span></span><span class="arraycolsep" style="width:1em;"></span><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.69em;"><span style="top:-3.69em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord">∃</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">满足关系的物体对</span></span></span></span><span style="top:-2.25em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">否则</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.19em;"><span></span></span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>视频级得分是逐帧平均。这里用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span></span></span></span> 而非常数 1，直觉是：两个框重叠得越厉害，&quot;左右&quot;这个断言就越没有意义，因此重叠度直接充当惩罚项。代价是这个分数把<strong>关系正确性</strong>与<strong>物体分离度</strong>混在了一起——两个正确分开的物体天然比两个贴在一起的物体得分高，即使后者的左右关系同样正确。</p><p>运动绑定的核心是相对运动。记前景点集与背景点集在整段视频上的平均运动向量为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8539em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8539em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">bg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，真实运动方向取</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8539em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">bg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span></span></span></span></span></p><p>再判断 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 是否落在 prompt 指定的方向象限内。减去 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8539em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">bg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 就是在做一次朴素的相机运动补偿——这正是 VideoDirectorGPT 的首末帧法所缺的一步。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：这些自制指标真的比通用指标更贴近人类吗？</strong> 每类随机抽 15 条 prompt、用 6 个 T2V 模型各生成一段（另加动态属性 10 段、物体交互 11 段真实视频作参照），共 651 段视频，在 Amazon Mechanical Turk 上每段由 3 位标注者打对齐分，与自动分算 Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 与 Spearman <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>。结果支持了&quot;分类配器&quot;的设计：一致属性绑定上 Grid-LLaVA 取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.6636</span></span></span></span>，而 CLIP 只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.3667</span></span></span></span>；空间关系上 G-Dino <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5769</span></span></span></span> 对 VPEval-S <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.3137</span></span></span></span>；运动绑定上 DOT <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4523</span></span></span></span> 对 M-GDino <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2059</span></span></span></span>；动态属性绑定上逐帧的 D-LLaVA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4362</span></span></span></span> 远超视频级的 Grid-LLaVA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1435</span></span></span></span>。值得注意的负面证据：PLLaVA 在空间关系（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.1252</span></span></span></span>）与物体交互（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.2233</span></span></span></span>）上与人类<strong>负相关</strong>，说明&quot;换个更强的 video LLM&quot;并不自动带来更好的评测器。</p><p><strong>问题二：现有模型到底做得怎么样？</strong> 23 个模型（17 开源 + 6 商业）的结果按类别呈现出很陡的难度梯度。动态属性绑定是绝对的深渊，绝大多数模型落在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.008</span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.025</span></span></span></span> 区间，最高的 Gen-3 也只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0687</span></span></span></span>；运动绑定普遍在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.21</span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.29</span></span></span></span>；相比之下一致属性绑定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.40</span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.71</span></span></span></span>、物体交互 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.40</span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.83</span></span></span></span>。分组来看，diffusion U-Net 组里 T2V-Turbo-V2 最强（一致属性 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.6723</span></span></span></span>、动作绑定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.6087</span></span></span></span>），DiT 组里 CogVideoX-5B 最强，整体最强是商业模型 PixVerse-V3（动作绑定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.8722</span></span></span></span>、物体交互 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.8309</span></span></span></span>、数量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.6066</span></span></span></span>）。</p><p><strong>问题三：针对性设计是否有效？</strong> 从 VideoCrafter2 派生的 VideoTetris、Vico、T2V-Turbo-V2 在多数类别上都优于底座；LVD 的 LLM 布局规划让它在 U-Net 组的空间关系上领先；MagicTime 相对其底座 AnimateDiff 在动态属性上从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0097</span></span></span></span> 升到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0151</span></span></span></span>。这些提升在相对意义上成立，但绝对值仍然贴着地板。</p><p>作者在附录 G 明确承认的局限是：<strong>没有一个统一指标能覆盖全部七类</strong>，只能等更强的多模态模型出现。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频组合性是一个此前没有 benchmark 的独立能力轴；本文把它拆成 3 个空间类 + 4 个时间类共 1400 条必含动词的 prompt；每类配一个专用评测器（Grid-LLaVA / D-LLaVA / G-Dino / DOT），并用 651 段人工标注视频验证选型；23 个模型的结果显示动态属性绑定与运动绑定几乎是地板分；开源最强是 T2V-Turbo-V2 与 CogVideoX-5B，整体最强是商业模型 PixVerse-V3。</p><p><strong>3 句话版</strong>：组合性在视频里比图像多出&quot;跨帧动态&quot;这一维，通用指标看不见它。本文用分类配器的方式为七类误差各造一个传感器，并用人类相关性做选型验证。结论是当前模型在属性随时间变化与运动方向上基本不可用。</p><p><strong>1 句话版</strong>：想优化视频的组合性，先得有能分别看见语义绑定、空间布局和相对运动的三套尺子。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的假设是：<strong>&quot;每类的最佳评测器&quot;这个选型结论，可以从 651 段人工标注视频外推到 23 个模型 × 1400 条 prompt 的全量排行榜。</strong></p><p>问题在于选型与验证用的是同一批数据。每类只有 15 条 prompt、6 个模型、90 段视频，作者在这上面比较 10 余个候选指标并选出相关性最高者——这是典型的在验证集上选模型，没有留出独立测试集。当候选指标数量与样本量在同一量级时，被选中的指标有相当概率只是赢在噪声上。表 1 里若干组数值差距本身也不大（例如空间关系上 LLaVA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4258</span></span></span></span> 与 Grid-LLaVA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4815</span></span></span></span>），却足以改变选型结论。</p><p>论文为这个假设提供的证据是：被选中的指标在各自类别上确实显著高于 CLIP/B-CLIP/B-BLEU 这类通用指标（差距往往 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2</span></span></span></span> 以上）。这足以支持&quot;专用优于通用&quot;，但不足以支持&quot;这一个专用器是最优的&quot;。缺的是：在留出 prompt 上重测相关性，以及给出相关系数的置信区间。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要复现全部 23 个模型：</p><ul><li>数据：从 T2V-CompBench 公开的 spatial 与 numeracy 两类里各取 60 条 prompt，用两个开源模型（如 VideoCrafter2 与 CogVideoX-5B）各生成 1 段，共 240 段。</li><li>实现：只跑 G-Dino 分支（GroundingDINO + 规则判定），无需 MLLM。</li><li>测量：自己招 3 名标注者对同一批视频打 5 级对齐分，把 240 段随机切成两半，在前一半上做&quot;指标选型&quot;（比较 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span></span></span></span> 加权与常数 1 加权两种变体、以及 16 帧与 6 帧两种采样），在后一半上报告选中变体的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>。</li><li>判据：若留出集上的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 相对选型集下降不超过 0.05，说明选型稳健，支持原文结论；若下降超过 0.15，或选出的变体在留出集上不再是最优，则说明表 1 的选型部分是过拟合，需要更大的人工标注集。</li></ul><p>这个实验的成本主要在标注（240 段 × 3 人），指标侧完全是现成模型的推理。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对<strong>动态属性绑定</strong>这一列构造反例。全部 23 个模型的分数落在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.005</span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.069</span></span></span></span> 之间，跨度不到 7 个百分点，且最强的两个（Gen-3 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0687</span></span></span></span>、PixVerse-V3 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0624</span></span></span></span>）恰恰是作者自己指出&quot;动态度很高&quot;的两个模型。一个替代解释是：<strong>D-LLaVA 在这一档上度量的主要是画面变化幅度，而非属性变化的正确性</strong>。</p><p>具体设计：取任意一个模型，对同一批动态属性 prompt 生成两组视频——一组正常生成，另一组在生成后施加一个与语义无关的全局渐变（例如整段视频线性叠加一个色温漂移或亮度斜坡），使首末帧在像素上明显不同但属性绑定并未变正确。如果第二组的 D-LLaVA 分数显著上升，就证明该列的排名主要由&quot;画面是否在变&quot;驱动，而 Gen-3/PixVerse-V3 的领先是动态度的副产品而非组合能力。反过来，如果分数不动甚至下降，则 D-LLaVA 的构造（鼓励首帧对齐初态、末帧对齐终态、中间帧居中）确实抓住了方向性，原文结论得到强化。</p><p>这个反例之所以有力，是因为它同时给出了对现有排名的替代解释，并且指出了一个可预测的失败条件：当所有被测模型都贴着地板时，任何指标的排序都可能不携带信息。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文的 metric 是&quot;每类一个传感器&quot;，且全部是<strong>只读</strong>的——它们只给分数，不给可微或可定位的改进信号。这导致 benchmark 与后训练之间存在断层：知道模型在运动绑定上只有 0.22，却不知道该改哪里。</p><p><strong>(b) 借鉴工具</strong>：可以借鉴程序分析里的 <strong>fault localization</strong> 与因果推断里的 <strong>中介分析</strong>。把评测从&quot;给一个标量&quot;改成&quot;给一个反事实归因&quot;：对同一条 prompt，系统性地做最小语义扰动（把 &quot;leftwards&quot; 换成 &quot;rightwards&quot;、把 &quot;three&quot; 换成 &quot;four&quot;、把属性在两个物体间对调），观察生成分布如何变化。若模型对 &quot;left→right&quot; 的扰动完全无响应，说明方向词根本没进入生成路径；若响应但方向反了，说明是绑定错误而非忽略。这两种失败需要完全不同的修法（前者要改文本编码器或数据，后者要改注意力路由），而当前的标量分数无法区分。</p><p><strong>(c) 第一个实验</strong>：在运动绑定的 200 条 prompt 上构造成对的对比 prompt（原文已经在空间关系类做过&quot;左右反转&quot;的对比构造，可直接推广），对每个模型测量&quot;方向翻转后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 的期望翻转率&quot;。这个量与绝对得分正交：一个从不响应方向词的模型和一个总把方向搞反的模型可以有相同的绝对分，但翻转率一个是 0、一个接近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">1</span></span></span></span>。把它做成 T2V-CompBench 的第八个维度，才能把评测结果直接翻译成后训练的干预点。</p>',54)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
